{
  "name": "opencode-permission-audit",
  "version": "0.1.0",
  "description": "OpenCode plugin that records permission prompts and replies as local JSONL audit logs.",
  "type": "module",
  "license": "MIT",
  "author": "Francis",
  "repository": {
    "type": "git",
    "url": "git+ssh://git@github.com/prandelicious/opencode-permission-audit.git"
  },
  "bugs": {
    "url": "https://github.com/prandelicious/opencode-permission-audit/issues"
  },
  "homepage": "https://github.com/prandelicious/opencode-permission-audit#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "audit",
    "permissions",
    "jsonl"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./report": {
      "types": "./dist/report.d.ts",
      "import": "./dist/report.js"
    }
  },
  "types": "./dist/index.d.ts",
  "bin": {
    "opencode-permission-audit": "dist/cli.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsup src/index.ts src/report.ts src/cli.ts --format esm --dts --clean",
    "check": "bun run typecheck && bun run lint && bun run test",
    "format": "prettier --write .",
    "format:check": "prettier --check .",
    "install:local": "bun scripts/install-local.mjs",
    "lint": "oxlint .",
    "prepack": "bun run build",
    "report": "bun src/cli.ts report",
    "test": "vitest run",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.30",
    "@opencode-ai/sdk": ">=1.14.30"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.14.30",
    "@opencode-ai/sdk": "1.14.30",
    "@types/node": "^20.12.12",
    "oxlint": "^1.0.0",
    "prettier": "^3.2.5",
    "tsup": "^8.0.2",
    "typescript": "^5.4.5",
    "vitest": "^1.6.0"
  },
  "engines": {
    "node": ">=20"
  },
  "packageManager": "bun@1.3.11"
}
